import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"物联网与云安全","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/物联网与云安全.md","filePath":"安全方向/物联网与云安全.md","lastUpdated":1792430298000}'),i={name:"安全方向/物联网与云安全.md"};function o(d,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="物联网与云安全" tabindex="-1">物联网与云安全 <a class="header-anchor" href="#物联网与云安全" aria-label="Permalink to &quot;物联网与云安全&quot;">​</a></h1><blockquote><p>新兴安全主战场。校内师资覆盖「物联网安全」「云计算与虚拟化安全」（舒兆港、陈日清等老师方向），契合 FAFU 农林信息化与智慧农业的应用场景。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>物联网设备（摄像头、传感器、智慧农业终端）普遍「裸奔」，是攻击面扩张最快的领域；</li><li>云计算成为企业基础设施，云安全（虚拟化隔离、容器安全、IAM）需求爆发；</li><li>农林特色：智慧林业、农业物联网的安全防护是 FAFU 的差异化优势方向。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/计算机网络.html">计算机网络</a>、<a href="./../专业基础/操作系统.html">操作系统</a></li><li><a href="./../必学工具/Docker.html">Docker</a>（云原生/容器安全基础）</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>物联网安全：设备固件分析、通信协议（MQTT/CoAP）、传感器安全、OTA 安全</li><li>云安全：虚拟化与 Hypervisor、容器（Docker/K8s）安全、云 IAM 与身份管理</li><li>典型风险：固件提取、协议重放、容器逃逸概念、错误配置（错误暴露的 S3/数据库）</li><li>防护思路：设备认证、安全更新、网络分段、最小权限</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《物联网安全》/ 相关教材</td><td>教材</td><td>方向入门</td></tr><tr><td>OWASP IoT Top 10</td><td>文档</td><td>物联网风险清单（<a href="https://owasp.org/www-project-internet-of-things/" target="_blank" rel="noreferrer">owasp.org</a>）</td></tr><tr><td><a href="https://cloudsecurityalliance.org/" target="_blank" rel="noreferrer">Cloud Security Alliance</a></td><td>组织</td><td>云安全权威机构与指南</td></tr><tr><td>TryHackMe / HTB 的 IoT 与云靶机</td><td>练习</td><td>动手练靶</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>结合农林场景选题（智慧农业设备、林业监测网络），既是特色也是毕设/竞赛好方向；</li><li>云安全学习路径：Linux → Docker → K8s 基础 → 云架构 → 云安全基线（CIS Benchmarks）；</li><li>关注学院实验室设备（物联网安全智能监控平台等），主动申请参与项目。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>物联网安全（方向课）</li><li>云计算与虚拟化安全（方向课）</li></ul>',14)])])}const b=a(i,[["render",o]]);export{_ as __pageData,b as default};
